assets.styles.css:
/* Gazette: the story as tomorrow's front page. Black ink, heavy rules, one red, headlines in heavy serif. */

/* Headlines: heavy, tight, set like a front page. */
[data-part="shell.title"] h1, [data-part="settings.page-head"] h1, [data-part="scenes.header"] h1,
[data-part="library.section.header"] h2, [data-part="ui.section-header"] h2 {
  font-family: var(--font-fancy) !important; font-weight: 900 !important; letter-spacing: -0.025em; text-transform: none;
}
[data-part="scenes.header"], [data-part="settings.page-head"], [data-part="library.section.header"] {
  border-top: 5px solid var(--bk-line-strong); border-bottom: 1px solid var(--bk-line-strong); box-shadow: 0 3px 0 -2px var(--bk-line-strong);
}

/* The scene header is a masthead: a heavy rule over a hairline, the name in black letter weight. */
.scs .sh { background: var(--bk-surface-base) !important; border-top: 4px solid var(--bk-line-strong); border-bottom: 3px double var(--bk-line-strong) !important; }
.scs .sh .nm { font-family: var(--font-fancy) !important; font-weight: 900 !important; letter-spacing: -0.01em !important; text-transform: none !important; font-size: 1.15em !important; }
.scs .sh .tag { font-style: italic; }

/* Plain newsprint behind the story, with a column rule down the gutter. */
.scs .bgm { background: var(--bk-surface-base) !important; }

/* Bylines: a red square, then the speaker in spaced capitals. */
.scs .msg .spk { font-family: var(--font-ui) !important; font-weight: 800 !important; letter-spacing: .16em !important; color: var(--bk-text) !important; }
.scs .msg.char .spk::before { content: ""; display: inline-block; width: .62em; height: .62em; margin-right: .5em; background: var(--bk-role-brand); vertical-align: .02em; }

/* A drop cap opens every reply that runs to more than one paragraph. */
.scs .msg.char .prose:has(> .blk + .blk) > .blk:first-child::first-letter {
  float: left; font-family: var(--font-fancy); font-weight: 900; font-size: 3.4em; line-height: .82;
  padding: .06em .1em 0 0; color: var(--bk-role-brand-text);
}
.scs .msg .prose { line-height: 1.6; }

/* Long replies set in two columns with a hairline rule, the way a feature runs. */
@container (min-width: 820px) {
  .scs .msg.char .prose:has(> .blk + .blk) { column-count: 2; column-gap: 2.2em; column-rule: 1px solid var(--bk-line); }
}

/* The reader's lines are letters to the editor: indented, under a short rule. */
.scs .msg.user .body { border-top: 2px solid var(--bk-line-strong); padding-top: 10px !important; }
.scs .msg.user .prose { font-style: italic; }

/* Pictures print in halftone black and white, and come back to colour when you look closer. */
.scs .msg .por, [data-part="library.card"] img, [data-part="scenes.card"] img, [data-part="scenes.hero"] img {
  filter: grayscale(1) contrast(1.08); transition: filter var(--bk-dur-slow) var(--bk-ease-move);
}
.scs .msg:hover .por, [data-part="library.card"]:hover img, [data-part="scenes.card"]:hover img, [data-part="scenes.hero"]:hover img { filter: none; }
.scs .msg .por { border: 1px solid var(--bk-line-strong) !important; }

/* The composer is a typewriter line under a heavy rule. */
.scs .dockbar .cap { border-top: 3px solid var(--bk-line-strong) !important; background: var(--bk-surface-field) !important; }

/* The dock is a black ticker bar with white type. */
[data-part="shell.nav"] nav { background: var(--bk-text) !important; border: 0 !important; box-shadow: 0 0 0 1px var(--bk-text), 0 0 0 3px var(--bk-surface-base), 0 0 0 4px var(--bk-text) !important; }
[data-part="shell.nav"] nav [data-part="shell.nav.tile"], [data-part="shell.nav"] nav [data-part="shell.nav.overlay"] { color: var(--bk-surface-base) !important; background: transparent !important; }
[data-part="shell.nav"] nav [data-part="shell.nav.tile"]:hover { background: color-mix(in srgb, var(--bk-surface-base) 14%, transparent) !important; }
[data-part="shell.nav"] nav [data-part="shell.nav.tile"][aria-current="page"] { background: var(--bk-role-brand) !important; color: var(--bk-text-on-deep) !important; }
[data-part="shell.nav"] nav > span[aria-hidden="true"] { background: color-mix(in srgb, var(--bk-surface-base) 40%, transparent) !important; }
